<?php $pageTitle='Assessments'; require 'config.php'; require 'includes/functions.php'; require_role('student');$uid=user()['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){ $aid=(int)$_POST['assessment_id'];$score=random_int(55,98);$integrity=random_int(80,100);$pdo->prepare('INSERT INTO assessment_attempts(assessment_id,user_id,score,integrity_score,status,completed_at) VALUES(?,?,?,?,?,NOW())')->execute([$aid,$uid,$score,$integrity,'completed']);if($score>=70){$sid=(int)$_POST['skill_id'];$pdo->prepare('UPDATE user_skills SET verified=1, verified_at=NOW() WHERE user_id=? AND skill_id=?')->execute([$uid,$sid]);$pdo->prepare('UPDATE users SET trust_score=LEAST(100,trust_score+5) WHERE id=?')->execute([$uid]);$pdo->prepare('INSERT INTO trust_score_logs(user_id,change_amount,reason) VALUES(?,?,?)')->execute([$uid,5,'Passed skill assessment']);}flash('success',"Assessment completed. Score: $score%, Integrity: $integrity%.");header('Location: assessments.php');exit;}
$stmt=$pdo->prepare('SELECT us.skill_id,us.level,s.name skill_name,a.id assessment_id,a.title FROM user_skills us JOIN skills s ON s.id=us.skill_id LEFT JOIN assessments a ON a.skill_id=s.id AND a.level=us.level WHERE us.user_id=?');$stmt->execute([$uid]);$rows=$stmt->fetchAll();$hist=$pdo->prepare('SELECT aa.*,a.title FROM assessment_attempts aa JOIN assessments a ON a.id=aa.assessment_id WHERE aa.user_id=? ORDER BY aa.completed_at DESC');$hist->execute([$uid]);$hist=$hist->fetchAll();include 'includes/header.php';?>
<div class="card"><h1>Skill Assessments</h1><p class="muted">Demo assessment engine: start an assessment for a declared skill. Production webcam/gaze monitoring, server timers and code execution require separate services and explicit consent/security controls.</p></div><div class="grid section-title"><?php foreach($rows as $r):?><div class="card"><span class="badge">Level <?=e($r['level'])?></span><h3><?=e($r['skill_name'])?></h3><?php if($r['assessment_id']):?><form method="post"><input type="hidden" name="assessment_id" value="<?=$r['assessment_id']?>"><input type="hidden" name="skill_id" value="<?=$r['skill_id']?>"><button class="btn">Take Assessment</button></form><?php else:?><p class="muted">Assessment not seeded for this level.</p><?php endif;?></div><?php endforeach;?></div><h2 class="section-title">Assessment History</h2><div class="table-wrap card"><table class="table"><tr><th>Assessment</th><th>Score</th><th>Integrity</th><th>Date</th></tr><?php foreach($hist as $h):?><tr><td><?=e($h['title'])?></td><td><?=e($h['score'])?>%</td><td><?=e($h['integrity_score'])?>%</td><td><?=e($h['completed_at'])?></td></tr><?php endforeach;?></table></div>
<?php include 'includes/footer.php'; ?>
